INSERT INTO `pages` VALUES (1,'reagecon','Reagecon','<table><thead><tr><th>SKU</th><th>Title</th><th>Price</th><th>Cart Form</th></tr></thead></table><p>Products not found</p>',NULL,'Reagecon - Lab Supply',NULL,1,0,'2026-11-15 20:39:36','2026-11-15 20:39:36'),(2,'diskusi-produk','Diskusi Produk','<h2>Kami buka ruang untuk anda konsultasi dan bertanya terkait produk</h2>',NULL,'Diskusi Produk - Lab Supply',NULL,1,0,'2026-11-15 20:39:36','2026-11-15 20:39:36'),(3,'shopping-faq','Frequently Asked Questions','<p><strong>Terakhir diperbarui:</strong> 8 Oktober 2025</p><p>Selamat datang di halaman FAQ <strong>LabSupply.id</strong>!</p><p>Kami mengumpulkan pertanyaan yang paling sering diajukan pelanggan agar Anda bisa mendapatkan jawaban cepat sebelum melakukan pembelian.</p><h3><strong>1. Tentang Produk</strong></h3><p><strong>Q: Apakah semua produk di LabSupply.id baru dan original?</strong></p><p>A: Ya, semua produk yang kami jual adalah <strong>barang baru dan original</strong> dari produsen atau distributor resmi. Kami tidak menjual produk bekas, rekondisi, atau tiruan.</p><p><strong>Q: Apakah produk di LabSupply.id sudah termasuk panduan atau manual penggunaan?</strong></p><p>A: Setiap alat laboratorium biasanya disertai <strong>manual penggunaan</strong> dalam bahasa Inggris atau bahasa produsen. Jika Anda butuh panduan tambahan, tim kami siap bantu via email.</p><p><strong>Q: Apakah alat laboratorium di sini bisa digunakan untuk pendidikan maupun industri?</strong></p><p>A: Bisa. Produk kami dirancang untuk <strong>sekolah, universitas, laboratorium penelitian, maupun kebutuhan industri</strong>.</p><p><strong>Q: Apakah semua produk ready stock?</strong></p><p>A: Sebagian besar produk kami <strong>pre-order</strong> dengan waktu pengiriman sekitar <strong>30 hari kerja</strong>, tergantung ketersediaan dan lokasi pengiriman.</p><h3><strong>2. Pengiriman &amp; Estimasi Waktu</strong></h3><p><strong>Q: Kapan pesanan saya dikirim?</strong></p><p>A: Pengiriman dilakukan setelah kami menerima <strong>konfirmasi pembayaran</strong>. Proses pengemasan hingga pengiriman memakan waktu sekitar <strong>7–10 hari kerja</strong> sebelum dikirim melalui kurir internasional.</p><p><strong>Q: Berapa lama estimasi pengiriman ke Indonesia?</strong></p><p>A: Rata-rata <strong>20–30 hari kerja</strong>, tergantung lokasi, bea cukai, dan layanan ekspedisi yang digunakan (DHL, FedEx, UPS, dll).</p><p><strong>Q: Apakah saya bisa melacak pesanan saya?</strong></p><p>A: Tentu. Setelah barang dikirim, Anda akan menerima <strong>nomor resi (tracking number)</strong> untuk memantau status pengiriman secara real-time.</p><p><strong>Q: Apakah LabSupply.id melayani pengiriman internasional?</strong><br></br>A: Ya. Kami melayani pengiriman ke berbagai negara menggunakan mitra logistik global terpercaya.</p><p><strong>Q: Apa yang harus saya lakukan jika paket terlambat?</strong></p><p>A: Silakan hubungi kami di <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong> atau melalui WhatsApp dengan menyertakan nomor pesanan Anda. Kami akan bantu follow up ke pihak ekspedisi.</p><h3><strong>3. Pembayaran</strong></h3><p><strong>Q: Metode pembayaran apa saja yang diterima?</strong></p><p>A: Saat ini kami menerima pembayaran melalui <strong>transfer bank</strong> ke rekening resmi LabSupply.id. Detail rekening akan muncul di halaman checkout.</p><p><strong>Q: Apakah saya bisa bayar menggunakan e-wallet?</strong></p><p>A: Untuk saat ini belum, tapi kami sedang menyiapkan opsi pembayaran lain seperti e-wallet dan virtual account.</p><p><strong>Q: Apakah saya perlu mengirim bukti transfer?</strong></p><p>A: Ya. Setelah transfer, silakan kirim <strong>bukti pembayaran</strong> melalui email atau WhatsApp agar kami bisa memproses pesanan Anda lebih cepat.</p><p><strong>Q: Bagaimana jika saya salah transfer atau nominalnya kurang?</strong></p><p>A: Segera hubungi kami di <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong> dengan bukti transfer, dan kami bantu koreksi manual selama pesanan belum diproses.</p><h3><strong>4. Retur, Refund, dan Garansi</strong></h3><p><strong>Q: Apakah saya bisa mengembalikan barang yang sudah dibeli?</strong></p><p>A: Kami <strong>tidak menerima pengembalian barang</strong> kecuali dalam kondisi tertentu seperti produk rusak atau tidak sesuai pesanan (lihat kebijakan Return &amp; Refund kami).</p><p><strong>Q: Bagaimana cara klaim garansi produk?</strong></p><p>A: Produk kami dilindungi oleh <strong>garansi 1 tahun</strong> dari produsen. Anda hanya perlu mengirim email dengan bukti pembelian dan foto kondisi produk.</p><p><strong>Q: Apakah ada biaya tambahan untuk klaim garansi?</strong></p><p>A: Tidak ada biaya klaim, tapi <strong>biaya pengiriman barang ke pusat servis ditanggung pembeli</strong>, kecuali kesalahan berasal dari pihak kami.</p><p><strong>Q: Produk saya rusak saat diterima, apa yang harus saya lakukan?</strong></p><p>A: Foto kondisi produk segera dan kirim ke <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong> maksimal <strong>3 hari setelah diterima</strong>. Kami akan bantu proses penggantian sesuai kebijakan.</p><h3><strong>5. Pemesanan &amp; Akun</strong></h3><p><strong>Q: Apakah saya perlu membuat akun untuk berbelanja?</strong></p><p>A: Tidak wajib, tapi kami sarankan buat akun agar Anda bisa memantau status pesanan dan histori pembelian dengan lebih mudah.</p><p><strong>Q: Bagaimana cara memesan produk di LabSupply.id?</strong></p><p>A: Pilih produk → Tambahkan ke keranjang → Lanjutkan ke checkout → Isi data lengkap → Transfer pembayaran → Kirim bukti transfer → Tunggu konfirmasi dari kami.</p><p><strong>Q: Apakah bisa pesan dalam jumlah besar (wholesale)?</strong></p><p>A: Bisa banget. Untuk pemesanan skala besar atau lembaga pendidikan, hubungi kami melalui email agar kami bisa buatkan penawaran khusus.</p><h3><strong>6. Lainnya</strong></h3><p><strong>Q: Apakah harga di situs sudah termasuk pajak dan ongkir?</strong></p><p>A: Harga yang tertera <strong>belum termasuk pajak impor dan ongkos kirim internasional</strong>, kecuali disebutkan lain di halaman produk.</p><p><strong>Q: Apakah LabSupply.id menerima kerja sama distribusi atau reseller?</strong></p><p>A: Kami terbuka untuk kerja sama B2B dan distributor. Silakan kontak kami di <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong> untuk detail lebih lanjut.</p><p><strong>Q: Siapa yang bisa saya hubungi untuk pertanyaan teknis produk?</strong></p><p>A: Tim support kami siap bantu. Kirim pertanyaan teknis ke <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong>, dan kami akan meneruskan ke spesialis produk terkait.</p><h3><strong>Masih Punya Pertanyaan Lain?</strong></h3><p>Jangan ragu untuk menghubungi kami:</p><p><strong>Email:</strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a><br></br><strong>WhatsApp / Telepon:</strong><a href=\"http://wa.me/628111174992\" rel=\"noopener\">+62 811-1174-992</a><br></br><strong>Alamat:</strong> Ruko No. 8 Green Residence – Jl. Pangeran Sogiri, RT.01/RW.01, Kecamatan Tanah Baru, Bogor Utara 16154</p><p>Kami siap membantu Anda mendapatkan alat laboratorium terbaik dengan layanan yang profesional dan aman.</p>',NULL,'Frequently Asked Questions - Lab Supply',NULL,1,0,'2026-11-15 20:39:36','2026-11-15 20:39:36'),(4,'dmca','DMCA Policy','<p><strong>Terakhir diperbarui:</strong> 8 Oktober 2025</p><p>Di <strong>LabSupply.id</strong>, kami menghormati hak kekayaan intelektual semua pihak dan mengharapkan hal yang sama dari pengguna situs kami.<br></br>Kebijakan ini menjelaskan bagaimana kami menangani <strong>laporan pelanggaran hak cipta</strong> berdasarkan <strong>Digital Millennium Copyright Act (DMCA)</strong> serta hukum hak cipta yang berlaku di Indonesia dan secara internasional.</p><h3><strong>1. Kepemilikan Konten</strong></h3><p>Semua konten yang ditampilkan di situs <strong><a href=\"https://labsupply.id\" rel=\"noopener\">https://labsupply.id</a></strong> termasuk namun tidak terbatas pada:</p><ul><li><p>Teks, deskripsi produk, dan panduan teknis,</p></li><li><p>Foto produk dan ilustrasi,</p></li><li><p>Desain grafis, logo, serta tata letak halaman,</p></li></ul><p>adalah milik <strong>LabSupply.id</strong> atau digunakan di bawah lisensi resmi.<br></br>Penggunaan konten kami tanpa izin tertulis dapat dianggap sebagai pelanggaran hak cipta.</p><h3><strong>2. Penggunaan yang Diizinkan</strong></h3><p>Pelanggan atau pengunjung situs diperbolehkan:</p><ul><li><p>Mengunduh atau mencetak informasi produk <strong>untuk keperluan pribadi</strong> atau referensi pembelian.</p></li><li><p>Membagikan tautan ke halaman produk kami <strong>tanpa mengubah atau menghapus sumber aslinya</strong>.</p></li></ul><p>Namun, dilarang keras untuk:</p><ul><li><p>Menyalin deskripsi, foto, atau konten situs untuk digunakan di situs lain.</p></li><li><p>Menggunakan nama atau logo <strong>LabSupply.id</strong> untuk promosi tanpa izin tertulis.</p></li><li><p>Mengedit, memodifikasi, atau menjual ulang materi milik kami.</p></li></ul><h3><strong>3. Laporan Pelanggaran Hak Cipta (DMCA Takedown Notice)</strong></h3><p>Jika Anda adalah pemilik hak cipta dan yakin bahwa karya Anda digunakan di <strong>LabSupply.id</strong> tanpa izin, Anda dapat mengajukan <strong>permintaan penghapusan (DMCA Takedown Notice)</strong> dengan mengirimkan informasi berikut ke email kami di <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong>:</p><ol><li><p>Identifikasi karya berhak cipta yang diklaim dilanggar.</p></li><li><p>Tautan URL atau lokasi spesifik di situs kami tempat materi tersebut muncul.</p></li><li><p>Bukti bahwa Anda adalah pemilik hak cipta atau berwenang bertindak atas nama pemiliknya.</p></li><li><p>Informasi kontak lengkap (nama, alamat, nomor telepon, email).</p></li><li><p>Pernyataan bahwa Anda yakin dengan itikad baik bahwa penggunaan materi tersebut tidak diizinkan oleh pemilik hak cipta.</p></li><li><p>Pernyataan bahwa semua informasi dalam laporan Anda akurat dan Anda memahami bahwa memberikan pernyataan palsu dapat menimbulkan konsekuensi hukum.</p></li></ol><p>Kami akan meninjau laporan Anda dan, jika valid, <strong>menghapus atau menonaktifkan akses ke materi tersebut dalam waktu yang wajar</strong>.</p><h3><strong>4. Hak Kami</strong></h3><p>Kami berhak:</p><ul><li><p>Menghapus konten yang dianggap melanggar hak cipta tanpa pemberitahuan sebelumnya.</p></li><li><p>Menangguhkan atau menutup akun pengguna yang berulang kali melakukan pelanggaran hak cipta.</p></li><li><p>Melaporkan dugaan penyalahgunaan kepada pihak berwenang jika diperlukan.</p></li></ul><h3><strong>5. Penolakan Tanggung Jawab</strong></h3><p>Kami tidak bertanggung jawab atas konten yang diunggah atau dibagikan oleh pihak ketiga (misalnya komentar, ulasan produk, atau testimoni pelanggan).<br></br>Namun, kami akan menindak setiap laporan pelanggaran hak cipta yang valid sesuai kebijakan ini.</p><h3><strong>6. Perubahan Kebijakan</strong></h3><p>Kami dapat memperbarui kebijakan DMCA ini kapan saja tanpa pemberitahuan sebelumnya.<br></br>Perubahan akan berlaku segera setelah dipublikasikan di halaman ini.</p><h3><strong>7. Kontak Kami</strong></h3><p>Untuk laporan atau pertanyaan terkait DMCA, hubungi kami di:</p><p><strong>Email:</strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a><br></br><strong>Alamat:</strong> [Isi alamat bisnis kamu di sini]<br></br><strong>WhatsApp / Telepon:</strong><a href=\"http://wa.me/628111174992\" rel=\"noopener\">+62 811-1174-992</a></p><blockquote><p>Dengan mengakses situs <strong>LabSupply.id</strong>, Anda menyetujui untuk menghormati seluruh hak kekayaan intelektual yang berlaku dan mematuhi kebijakan DMCA ini.</p></blockquote>',NULL,'DMCA Policy - Lab Supply',NULL,1,0,'2026-11-15 20:39:36','2026-11-15 20:39:36'),(5,'return-refund-policy','Return & Refund Policy','<p><strong>Terakhir diperbarui: </strong>8 Oktober 2025</p><p>Terima kasih telah berbelanja di <strong>LabSupply.id</strong>.\\</p><p>Kami menghargai setiap pelanggan dan berkomitmen untuk memberikan produk berkualitas tinggi.<br></br>Kebijakan ini menjelaskan syarat dan ketentuan terkait <strong>pengembalian barang (return)</strong> dan <strong>pengembalian dana (refund)</strong> di situs kami <strong><a href=\"https://labsupply.id\" rel=\"noopener\">https://labsupply.id</a></strong>.</p><h3><strong>1. Kebijakan Umum</strong></h3><p>Sebagian besar produk yang dijual di <strong>LabSupply.id</strong> adalah <strong>alat laboratorium fisik</strong> yang bersifat khusus dan dibuat untuk kebutuhan teknis tertentu.<br></br>Oleh karena itu, <strong>kami tidak menerima pengembalian atau refund</strong> kecuali dalam kondisi tertentu sebagaimana dijelaskan di bawah ini.</p><h3><strong>2. Kondisi yang Memenuhi Syarat Pengembalian</strong></h3><p>Anda dapat mengajukan pengembalian hanya jika memenuhi salah satu kondisi berikut:</p><ul><li><p>Produk <strong>rusak atau cacat</strong> saat diterima.</p></li><li><p>Produk yang dikirim <strong>tidak sesuai</strong> dengan pesanan Anda (misalnya jenis, model, atau spesifikasi berbeda).</p></li></ul><p>Untuk klaim seperti ini, pelanggan wajib:</p><ol><li><p>Menghubungi kami melalui email <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong> dalam waktu <strong>maksimal 3 hari setelah produk diterima</strong>.</p></li><li><p>Menyertakan <strong>foto atau video bukti kerusakan / ketidaksesuaian</strong> produk.</p></li><li><p>Menyimpan kemasan asli, invoice, dan semua aksesoris produk hingga proses selesai.</p></li></ol><p>Permintaan di luar periode 3 hari <strong>tidak dapat kami proses</strong>.</p><h3><strong>3. Produk yang Tidak Dapat Dikembalikan</strong></h3><p>Kami <strong>tidak dapat menerima pengembalian</strong> untuk kondisi berikut:</p><ul><li><p>Produk telah digunakan, diubah, atau mengalami kerusakan akibat kesalahan penggunaan.</p></li><li><p>Produk tanpa kemasan asli atau segel garansi rusak.</p></li><li><p>Produk pre-order atau pesanan khusus (custom order).</p></li><li><p>Permintaan pengembalian karena perubahan pikiran (misalnya: “tidak jadi butuh” atau “salah beli”).</p></li></ul><h3><strong>4. Proses Pengembalian</strong></h3><p>Jika pengembalian disetujui, pelanggan wajib:</p><ul><li><p>Mengirimkan produk ke alamat yang kami informasikan via email.</p></li><li><p>Menanggung biaya pengiriman barang kembali, kecuali kesalahan berasal dari pihak <strong>LabSupply.id</strong>.</p></li><li><p>Setelah produk kami terima dan diverifikasi, kami akan menawarkan <strong>penggantian produk baru</strong> atau <strong>perbaikan</strong> sesuai kondisi garansi.</p></li></ul><h3><strong>5. Kebijakan Pengembalian Dana (Refund)</strong></h3><p>Kami hanya akan melakukan <strong>refund</strong> apabila:</p><ul><li><p>Produk pengganti tidak tersedia, atau</p></li><li><p>Permintaan refund disetujui secara tertulis oleh pihak <strong>LabSupply.id</strong>.</p></li></ul><p>Dana akan dikirim kembali melalui metode pembayaran yang sama (transfer bank) dalam waktu <strong>7–14 hari kerja</strong> setelah persetujuan refund.</p><h3><strong>6. Garansi Produk</strong></h3><p>Beberapa produk kami dilindungi oleh <strong>garansi 1 tahun</strong> dari produsen atau distributor resmi.<br></br>Garansi mencakup cacat produksi, bukan kesalahan penggunaan atau kerusakan akibat kecelakaan.<br></br>Untuk klaim garansi, silakan hubungi kami di <strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a></strong> dengan melampirkan bukti pembelian.</p><h3><strong>7. Pengiriman Internasional</strong></h3><p>Untuk pengiriman internasional, pelanggan bertanggung jawab atas <strong>biaya pengiriman, bea cukai, dan pajak lokal</strong> yang berlaku.<br></br>Kami tidak dapat memberikan refund jika barang ditolak oleh bea cukai negara tujuan atau terlambat karena proses kepabeanan.</p><h3><strong>8. Kontak Kami</strong></h3><p>Jika Anda memiliki pertanyaan atau ingin mengajukan klaim pengembalian, hubungi kami melalui:</p><p><strong>Email:</strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a><br></br><strong>Alamat:</strong> [Isi alamat bisnis kamu di sini]<br></br><strong>WhatsApp / Telepon:</strong><a href=\"http://wa.me/628111174992\" rel=\"noopener\">+62 811-1174-992</a></p><blockquote><p>Dengan melakukan pembelian di <strong>LabSupply.id</strong>, Anda dianggap telah membaca, memahami, dan menyetujui seluruh ketentuan dalam Kebijakan Pengembalian &amp; Refund ini.</p></blockquote>',NULL,'Return & Refund Policy - Lab Supply',NULL,1,0,'2026-11-15 20:39:36','2026-11-15 20:39:36'),(6,'terms-and-conditions','Terms and Conditions','<p><strong>Terakhir diperbarui:</strong> 8 Oktober 2025</p><p>Selamat datang di <strong>LabSupply.id</strong></p><p>Dengan mengakses dan menggunakan situs web <strong><a href=\"https://labsupply.id\" rel=\"noopener\">https://labsupply.id</a></strong>, Anda menyetujui untuk terikat oleh Syarat &amp; Ketentuan berikut ini.<br></br>Harap baca dengan cermat sebelum menggunakan layanan kami.</p><h3><strong>1. Penggunaan Situs</strong></h3><p>Dengan mengakses situs ini, Anda menyatakan bahwa:</p><ul><li><p>Anda berusia minimal 18 tahun atau menggunakan situs ini di bawah pengawasan orang tua/wali yang sah.</p></li><li><p>Anda setuju untuk menggunakan situs hanya untuk tujuan yang sah dan tidak melanggar hukum.</p></li><li><p>Anda tidak akan mencoba meretas, mengganggu, atau merusak sistem keamanan situs.</p></li></ul><p>Kami berhak menolak akses atau layanan kepada siapa pun tanpa pemberitahuan sebelumnya jika ditemukan pelanggaran terhadap ketentuan ini.</p><h3><strong>2. Informasi Produk</strong></h3><p>Kami berusaha menjaga agar seluruh deskripsi, spesifikasi, dan gambar produk di situs <strong>LabSupply.id</strong> akurat dan terbaru.<br></br>Namun, <strong>kami tidak menjamin</strong> bahwa semua informasi sepenuhnya bebas dari kesalahan atau kekeliruan teknis.</p><p>Harga dan ketersediaan produk dapat berubah sewaktu-waktu tanpa pemberitahuan.<br></br>Jika terdapat kesalahan harga pada saat pemesanan, kami berhak membatalkan transaksi dan mengembalikan dana yang sudah dibayarkan (jika ada).</p><h3><strong>3. Pemesanan dan Pembayaran</strong></h3><ul><li><p>Semua pesanan dianggap <strong>sah</strong> setelah kami menerima konfirmasi pembayaran dari pelanggan melalui <strong>transfer bank</strong>.</p></li><li><p>Kami tidak bertanggung jawab atas kesalahan transfer dana ke rekening yang salah akibat kelalaian pelanggan.</p></li><li><p>Setelah pembayaran dikonfirmasi, kami akan memproses pesanan sesuai antrian dan estimasi pengiriman (sekitar <strong>30 hari kerja</strong>, tergantung lokasi).</p></li><li><p>Kami berhak menolak atau membatalkan pesanan jika ditemukan indikasi kecurangan atau data pelanggan tidak valid.</p></li></ul><h3><strong>4. Pengiriman dan Risiko</strong></h3><ul><li><p>Produk dikirim menggunakan jasa pengiriman seperti <strong>DHL, FedEx, UPS</strong>, dan layanan ekspedisi lain yang kami tunjuk.</p></li><li><p>Setelah barang diserahkan ke pihak kurir, <strong>risiko kerusakan atau kehilangan menjadi tanggung jawab pelanggan</strong>, kecuali produk memiliki asuransi pengiriman (jika tersedia).</p></li><li><p>Estimasi waktu pengiriman bersifat perkiraan dan dapat berubah karena faktor eksternal seperti cuaca, bea cukai, atau kondisi logistik internasional.</p></li></ul><h3><strong>5. Garansi Produk</strong></h3><ul><li><p>Produk tertentu dilindungi oleh <strong>garansi 1 tahun</strong> dari produsen atau distributor resmi.</p></li><li><p>Klaim garansi harus disertai bukti pembelian dan sesuai dengan ketentuan masing-masing produsen.</p></li><li><p>Garansi <strong>tidak mencakup</strong> kerusakan akibat kelalaian, penggunaan yang tidak sesuai, atau modifikasi produk.</p></li></ul><h3><strong>6. Kebijakan Pengembalian &amp; Refund</strong></h3><p>Kami <strong>tidak menyediakan refund atau retur</strong> kecuali dalam kondisi tertentu seperti:</p><ul><li><p>Produk rusak saat diterima.</p></li><li><p>Produk tidak sesuai dengan pesanan.</p></li></ul><p>Setiap klaim akan ditinjau secara individual dan harus disertai <strong>bukti foto/video</strong> serta laporan dalam waktu <strong>maksimal 3 hari setelah barang diterima</strong>.</p><p>Untuk detail lengkap, silakan baca halaman <strong>Return &amp; Refund Policy</strong> kami.</p><h3><strong>7. Hak Kekayaan Intelektual</strong></h3><p>Seluruh konten di situs <strong>LabSupply.id</strong> — termasuk logo, desain, teks, foto, dan gambar produk — dilindungi oleh hak cipta dan undang-undang yang berlaku di Indonesia.</p><p>Anda <strong>tidak diperbolehkan menyalin, mendistribusikan, atau menggunakan konten kami untuk tujuan komersial</strong> tanpa izin tertulis dari pihak <strong>LabSupply.id</strong>.</p><h3><strong>8. Batasan Tanggung Jawab</strong></h3><p>Dalam keadaan apa pun, <strong>LabSupply.id</strong> tidak bertanggung jawab atas:</p><ul><li><p>Kerugian langsung maupun tidak langsung akibat penggunaan situs atau produk.</p></li><li><p>Kesalahan teknis, keterlambatan pengiriman, atau gangguan layanan pihak ketiga.</p></li><li><p>Kerusakan akibat penggunaan produk yang tidak sesuai dengan panduan atau standar keselamatan laboratorium.</p></li></ul><h3><strong>9. Perubahan Ketentuan</strong></h3><p>Kami dapat memperbarui atau mengubah Syarat &amp; Ketentuan ini kapan saja tanpa pemberitahuan sebelumnya.<br></br>Perubahan akan berlaku segera setelah dipublikasikan di situs <strong>LabSupply.id</strong>.</p><h3><strong>10. Hukum yang Berlaku</strong></h3><p>Syarat &amp; Ketentuan ini diatur dan ditafsirkan sesuai <strong>hukum Republik Indonesia</strong>.<br></br>Setiap sengketa akan diselesaikan secara musyawarah terlebih dahulu, dan jika tidak tercapai kesepakatan, akan dibawa ke yurisdiksi pengadilan di Indonesia.</p><h3><strong>11. Kontak Kami</strong></h3><p>Jika Anda memiliki pertanyaan tentang Syarat &amp; Ketentuan ini, silakan hubungi kami:</p><p><strong>Email:</strong><a href=\"\" rel=\"noopener\">support@labsupply.id</a><br></br><strong>Alamat:</strong> [Isi alamat bisnis kamu di sini]<br></br><strong>WhatsApp / Telepon:</strong><a href=\"http://wa.me/628111174992\" rel=\"noopener\">+62 811-1174-992</a></p><blockquote><p>Dengan menggunakan situs ini, Anda menyetujui seluruh isi <strong>Syarat &amp; Ketentuan</strong> di atas.</p></blockquote>',NULL,'Terms and Conditions - Lab Supply',NULL,1,0,'2026-11-15 20:39:36','2026-11-15 20:39:36'),(7,'disclaimer','Disclaimer','<p><strong>Terakhir diperbarui:</strong> 8 Oktober 2025</p><p>Selamat datang di <strong>LabSupply.id</strong></p><p>Dengan mengakses dan menggunakan situs web kami di <strong><a href=\"https://labsupply.id\" rel=\"noopener\">https://labsupply.id,</a></strong> Anda dianggap telah membaca, memahami, dan menyetujui isi Disclaimer ini.</p><h3><strong>1. Informasi Umum</strong></h3><p>Semua informasi yang ditampilkan di situs <strong>LabSupply.id</strong> dimaksudkan untuk <strong>tujuan informasi umum</strong> dan <strong>promosi produk</strong> saja. Kami berusaha memastikan bahwa informasi, deskripsi, dan spesifikasi produk yang ditampilkan di situs ini <strong>akurat dan terbaru</strong>, namun <strong>kami tidak memberikan jaminan absolut</strong> atas kelengkapan, keandalan, atau ketepatan seluruh informasi tersebut.</p><p>Jika Anda mengambil tindakan berdasarkan informasi dari situs ini, Anda melakukannya atas risiko sendiri.<br></br><strong>LabSupply.id tidak bertanggung jawab</strong> atas kerugian atau kerusakan yang timbul dari penggunaan informasi di situs ini.</p><h3><strong>2. Produk dan Ketersediaan</strong></h3><p>Semua produk yang dijual melalui <strong>LabSupply.id</strong> adalah <strong>alat laboratorium fisik</strong>.<br></br>Ketersediaan produk, spesifikasi teknis, dan harga dapat berubah sewaktu-waktu tanpa pemberitahuan sebelumnya.</p><p>Kami berhak untuk <strong>menolak, membatalkan, atau menunda pesanan</strong> jika produk tidak tersed