INSERT INTO `posts` VALUES (1,'Cara Memilih Glassware yang Tepat untuk Laboratorium','cara-memilih-glassware-yang-tepat-untuk-laboratorium','Panduan singkat memilih glassware berdasarkan aplikasi, akurasi, dan bahan kimia yang digunakan.','<p>Panduan singkat memilih glassware berdasarkan aplikasi, akurasi, dan bahan kimia yang digunakan.</p><p>Tim Lab Supply menyediakan berbagai pilihan produk dan layanan pendukung untuk memastikan kegiatan laboratorium Anda berjalan lancar. Hubungi kami untuk konsultasi kebutuhan alat dan bahan laboratorium.</p>',NULL,1,'2026-11-13 18:54:16','2026-11-15 21:32:41','2026-11-16 18:54:16'),(2,'Tips Merawat Instrumen Laboratorium Agar Awet','tips-merawat-instrumen-laboratorium-agar-awet','Perawatan rutin sederhana yang dapat memperpanjang usia pakai instrumen laboratorium Anda.','<p>Perawatan rutin sederhana yang dapat memperpanjang usia pakai instrumen laboratorium Anda.</p><p>Tim Lab Supply menyediakan berbagai pilihan produk dan layanan pendukung untuk memastikan kegiatan laboratorium Anda berjalan lancar. Hubungi kami untuk konsultasi kebutuhan alat dan bahan laboratorium.</p>',NULL,1,'2026-11-13 18:54:16','2026-11-15 21:32:41','2026-11-16 18:54:16'),(3,'Mengenal Standar Kalibrasi Alat Ukur Laboratorium','mengenal-standar-kalibrasi-alat-ukur-laboratorium','Kenapa kalibrasi penting dan bagaimana memastikan alat ukur Anda selalu akurat.','<p>Kenapa kalibrasi penting dan bagaimana memastikan alat ukur Anda selalu akurat.</p><p>Tim Lab Supply menyediakan berbagai pilihan produk dan layanan pendukung untuk memastikan kegiatan laboratorium Anda berjalan lancar. Hubungi kami untuk konsultasi kebutuhan alat dan bahan laboratorium.</p>',NULL,1,'2026-11-13 18:54:16','2026-11-15 21:32:41','2026-11-16 18:54:16');
