INSERT INTO `products` VALUES (1,3,'Activated Carbon Lab-Grade 1kg','activated-carbon-lab-grade-1kg','LS-0001','','<p>Karbon aktif tingkat laboratorium (lab-grade) ini adalah adsorben serbaguna dengan kualitas premium, dirancang untuk memenuhi standar aplikasi ilmiah dan industri yang ketat. Produk 1kg ini memiliki <strong>Iodine Number 1000</strong> atau lebih tinggi, menunjukkan luas permukaan yang sangat besar dan kapasitas adsorpsi yang superior, membuatnya efektif untuk berbagai proses pemurnian.</p>',345000.00,NULL,25,'in_stock',NULL,NULL,1,1,14,0.00,0,'Activated Carbon Lab-Grade 1kg - Lab Supply','Karbon aktif tingkat laboratorium (lab-grade) ini adalah adsorben serbaguna dengan kualitas premium, dirancang untuk memenuhi standar aplikasi ilmiah dan i...','2026-11-15 20:39:01','2026-11-16 20:08:29'),(2,10,'Adjustable Pipette Stand','adjustable-pipette-stand','LS-0002','','<p>Dudukan pipet yang dapat disesuaikan tersedia dari berbagai produsen dan dirancang untuk menyimpan berbagai jenis dan ukuran pipet dengan aman, membantu mengatur ruang meja kerja dan mencegah kontaminasi. Dudukan ini tersedia dalam desain linier dan korsel, dengan pilihan yang terbuat dari bahan tahan bahan kimia seperti polipropilena atau plastik berkualitas tinggi.</p>',310000.00,NULL,25,'in_stock',NULL,NULL,1,1,9,0.00,0,'Adjustable Pipette Stand - Lab Supply','Dudukan pipet yang dapat disesuaikan tersedia dari berbagai produsen dan dirancang untuk menyimpan berbagai jenis dan ukuran pipet dengan aman, membantu me...','2026-11-15 20:39:02','2026-11-16 19:58:28'),(3,3,'Aluminum Weighing Boats 100 pcs','aluminum-weighing-boats-100-pcs','LS-0003','','<strong>Perahu Timbang Aluminium (Weighing Boats), 100 Pcs, Laboratorium</strong>Perahu timbang aluminium adalah wadah sekali pakai yang dirancang untuk keperluan laboratorium, khususnya untuk menimbang, memindahkan, atau mengeringkan sampel bahan padat atau cair.<strong>Fitur Utama:</strong><ul><li><strong>Bahan:</strong> Terbuat dari aluminium foil ringan namun kokoh.</li><li><strong>Jumlah:</strong> Umumnya dijual dalam kemasan isi 100 buah.</li><li><strong>Fungsi:</strong> Ideal untuk digunakan dengan neraca analitik atau mikro, tahan terhadap suhu tinggi, dan resistan terhadap sebagian besar bahan kimia laboratorium (asam dan basa encer).</li><li><strong>Desain:</strong> Memiliki bagian bawah yang rata untuk stabilitas, dinding yang berkerut untuk kekakuan, dan sering kali memiliki pegangan jari kecil untuk penanganan yang mudah.</li></ul>Produk ini penting untuk memastikan hasil penimbangan yang akurat dan bersih dalam berbagai aplikasi ilmiah.',190000.00,NULL,25,'in_stock',NULL,NULL,1,1,1,0.00,0,'Aluminum Weighing Boats 100 pcs - Lab Supply','Perahu Timbang Aluminium (Weighing Boats), 100 Pcs, Laboratorium\nPerahu timbang aluminium adalah wadah sekali pakai yang dirancang untuk keperluan laborato...','2026-11-15 20:39:03','2026-11-16 00:21:52'),(4,11,'Analytical Balance AB-200','analytical-balance-ab-200','LS-0004','','<p>neraca analitik dengan kapasitas maksimum sekitar 200 gram dan keterbacaan (readability) 0,1 miligram (0,0001 gram). Model spesifik bervariasi tergantung produsennya, seperti PCE-AB 200 dari PCE Instruments atau model dalam B-ONE AB Series</p>',9350000.00,NULL,25,'in_stock',NULL,NULL,1,1,0,0.00,0,'Analytical Balance AB-200 - Lab Supply','neraca analitik dengan kapasitas maksimum sekitar 200 gram dan keterbacaan (readability) 0,1 miligram (0,0001 gram). Model spesifik bervariasi tergantung p...','2026-11-15 20:39:04','2026-11-15 20:39:04'),(5,7,'Argon Cylinder 40L','argon-cylinder-40l','LS-0005','','<p>Tabung argon untuk plasma &amp; kromatografi</p><p>Tabung baja bertekanan tinggi yang umum digunakan untuk menyimpan gas argon industri atau medis, sering kali memiliki kapasitas sekitar 6 meter kubik (m³) gas. Tabung ini biasanya terbuat dari baja mulus berkekuatan tinggi.</p>',2500000.00,NULL,25,'in_stock',NULL,NULL,1,1,1,0.00,0,'Argon Cylinder 40L - Lab Supply','Tabung argon untuk